+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.core.ui.MainLayout;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H2;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.router.Location;
+import com.vaadin.flow.router.NavigationTrigger;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.theme.lumo.LumoUtility;
+import org.springframework.dao.DataAccessException;
+
+import java.util.stream.Stream;
+
+/** UC-002: Browse veterinarians and their specialties with infinite scrolling. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VetsView extends VerticalLayout {
+    private final transient VetRepository repository;
+
+    public VetsView(VetRepository repository) {
+        this.repository = repository;
+        setSizeFull();
+        H2 heading = new H2("Veterinarians");
+        heading.addClassNames(LumoUtility.Margin.NONE);
+
+        Grid<Vet> grid = new Grid<>();
+        grid.setSelectionMode(Grid.SelectionMode.NONE);
+        grid.getElement().setAttribute("aria-label", "Veterinarians");
+        grid.addColumn(Vet::firstName).setHeader("First Name");
+        grid.addColumn(Vet::lastName).setHeader("Last Name");
+        grid.addColumn(vet -> vet.specialties().isEmpty() ? "none"
+                : String.join(", ", vet.specialties())).setHeader("Specialties");
+        grid.setItems(query -> fetch(query.getOffset(), query.getLimit()), query -> count());
+        add(heading, grid);
+        expand(grid);
+    }
+
+    private Stream<Vet> fetch(int offset, int limit) {
+        try {
+            return repository.findPage(offset, limit);
+        } catch (DataAccessException exception) {
+            showError(exception);
+            return Stream.empty();
+        }
+    }
+
+    private int count() {
+        try {
+            return repository.count();
+        } catch (DataAccessException exception) {
+            showError(exception);
+            return 0;
+        }
+    }
+
+    // Lazy callbacks also run after navigation, outside the router's exception handler.
+    private void showError(DataAccessException exception) {
+        UI ui = UI.getCurrent();
+        ui.getInternals().getRouter().handleExceptionNavigation(ui, new Location("vets"),
+                exception, NavigationTrigger.PROGRAMMATIC, null);
+    }
+}
